{
  "name": "函数发生器",
  "name_en": "Function Generator",
  "manufacturer": "",
  "description": "函数发生器是一种电子测试仪器，用于产生可调频率、幅度、相位、直流偏置和波形类型的电信号。它常用于电子电路测试、传感器与执行器激励、教学实验以及通用信号源应用。",
  "description_en": "A function generator is an electronic test instrument that produces electrical signals with adjustable frequency, amplitude, phase, DC offset, and waveform type. It is commonly used for circuit testing, sensor and actuator excitation, teaching labs, and general-purpose signal source applications.",
  "actions": [
    {
      "action_name": "auto-amplitude",
      "description": "获取/设置输出幅度",
      "description_en": "Get/set the output amplitude"
    },
    {
      "action_name": "auto-frequency",
      "description": "获取/设置输出频率",
      "description_en": "Get/set the output frequency"
    },
    {
      "action_name": "auto-function",
      "description": "获取/设置输出波形类型",
      "description_en": "Get/set the output waveform type"
    },
    {
      "action_name": "auto-offset",
      "description": "获取/设置输出直流偏置电压",
      "description_en": "Get/set the output DC offset voltage"
    },
    {
      "action_name": "auto-phase",
      "description": "获取/设置输出相位",
      "description_en": "Get/set the output phase"
    },
    {
      "action_name": "auto-channel",
      "description": "获取通道对象",
      "description_en": "Get a channel object"
    },
    {
      "action_name": "auto-sendcmd",
      "description": "向仪器发送原始命令",
      "description_en": "Send a raw command to the instrument"
    },
    {
      "action_name": "auto-query",
      "description": "向仪器发送查询命令并读取返回结果",
      "description_en": "Send a query command to the instrument and read the response"
    }
  ],
  "tag_hints": [
    "function generator",
    "waveform generation",
    "signal source",
    "frequency control",
    "amplitude control",
    "phase control",
    "DC offset"
  ]
}

